import {PLANT_MODEL,PLANT_DAYS,PLANT_CONDITIONS,PLANT_SPECIMENS,plantObservation,plantObservationById,plantQuestions,waterComparisonQuestion} from './plant-study-content.mjs';
import {plantStudy,currentPlantObservation,setPlantPage,setPlantDay,setPlantSpecimen,setPlantPrediction,recordPlantObservation,answerPlantQuestion,usePlantSupport,choosePlantLocation,carryPlantPlan,recoverPlantStudy} from './plant-study-core.mjs';
import {seedlingArt} from './plant-study-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const steps=[['predict','Wonder'],['observe','Inspect'],['compare','Compare'],['plan','Plan']];
const choices=[['light','Adequate light'],['dim','Too little light'],['similar','Similar lengths'],['unsure','I’m not sure yet']];
const locationName=id=>({light:'Adequate light',dim:'Too little light',unsure:'Still deciding'})[id];
const button=(attr,id,text,selected=false)=>`<button type="button" class="secondary ${selected?'selected':''}" data-ps-${attr}="${id}" ${selected?'aria-pressed="true"':'aria-pressed="false"'}>${text}</button>`;
const notice=()=>`<p class="ps-notice">${esc(PLANT_MODEL.notice)}</p>`;
function source(s){return `<section class="ps-source" aria-label="Seedling model"><div class="ps-source-top"><strong>Model day ${s.day} after emergence</strong><span>Stem length · millimeters (mm)</span></div>${notice()}<div class="ps-days" role="group" aria-label="Choose model day">${PLANT_DAYS.map(d=>button('day',d,`Day ${d}`,s.day===d)).join('')}</div><div class="ps-trays">${PLANT_CONDITIONS.map(c=>`<div class="ps-tray"><h3>${c.label}</h3><div class="ps-specimens">${PLANT_SPECIMENS.map(a=>{const row=plantObservation(s.day,c.id,a),selected=s.condition===c.id&&s.specimen===a;return `<button type="button" class="ps-plant ${selected?'selected':''}" data-ps-specimen="${c.id}:${a}" aria-pressed="${selected}" aria-label="Select ${c.label} specimen ${a}, ${row.stemMm} millimeters">${seedlingArt(row)}</button>`;}).join('')}</div></div>`).join('')}</div><details><summary>What stays alike? What can this model show?</summary><p>${esc(PLANT_MODEL.controls)}</p><p>These four invented seedlings illustrate a possible pattern. They cannot establish a real cause or predict every plant. Different species and situations need different light.</p><ul>${PLANT_MODEL.sources.map(x=>`<li><a href="${x.url}" target="_blank" rel="noopener">${esc(x.title)}</a></li>`).join('')}</ul></details></section>`;}
function keptTable(s){return `<details class="ps-notebook" ${s.page==='observe'?'open':''}><summary id="ps-notebook-title">My kept observations (${s.observations.length})</summary>${notice()}${s.observations.length?`<div class="ps-table-wrap"><table><caption>Copied model observations. Stem length from the soil surface.</caption><thead><tr><th>Day</th><th>Condition / specimen</th><th>Stem mm</th><th>What is pictured</th><th>Select</th></tr></thead><tbody>${s.observations.map(id=>{const r=plantObservationById(id);return `<tr><td>${r.day}</td><td>${r.conditionLabel} · ${r.specimen}</td><td>${r.stemMm}</td><td>${esc(r.leafColour)} leaves, ${r.leafSpreadMm} mm across; ${esc(r.stemForm)}</td><td>${button('row',id,'Use this observation',currentPlantObservation({plantStudy:s}).id===id)}</td></tr>`;}).join('')}</tbody></table></div>`:'<p>Choose a specimen, then keep its observation here.</p>'}<p class="tiny">Keeping a supplied row is collecting, not measuring a real seedling. A notebook can help us ask a question.</p></details>`;}
function question(q,s){const record=s.questions[q.id],last=record?.attempts.at(-1);return `<section class="ps-question"><h3>${esc(q.prompt)}</h3><div class="ps-choices">${q.choices.map(c=>`<button type="button" class="secondary ${last?.choice===c.id?'selected':''}" data-ps-answer="${q.id}:${c.id}" aria-pressed="${last?.choice===c.id}">${esc(c.label)}</button>`).join('')}</div>${last?`<p class="ps-feedback" id="ps-feedback-${q.id}" tabindex="-1" role="status">${esc(q.feedback[last.choice])}</p>`:''}<div data-ps-audio>${hearButton(q.prompt,'Hear this question')}</div></section>`;}
function task(s){const row=currentPlantObservation({plantStudy:s});if(s.page==='predict')return `<h2 id="ps-title" tabindex="-1">A shelf for the next seedlings</h2><p>The storm damaged the growing shelf. Before we rebuild it, let’s look closely at what light might change.</p><h3>Which seedlings do you think will have longer stems later?</h3><p>Make a guess, or inspect first. There’s no score for a prediction.</p><div class="ps-choices">${choices.map(([id,label])=>button('prediction',id,label,s.prediction.latest?.choice===id)).join('')}</div>${s.prediction.latest?`<p class="ps-feedback" id="ps-prediction" tabindex="-1" role="status">Your current idea: ${choices.find(([id])=>id===s.prediction.latest.choice)[1]}. ${s.prediction.latest.timing==='before-later-days'?'Kept before looking at later model days.':'Kept after later model days had been shown.'} Your first idea is also kept.</p>`:''}<button class="primary" type="button" data-ps-page="observe">Inspect the seedlings →</button>`;
 if(s.page==='observe')return `<h2 id="ps-title" tabindex="-1">What can you actually see?</h2><p>Tap a day and a labelled seedling. Compare its stem and leaves, then keep an observation that interests you.</p><div class="ps-selected"><h3>${row.conditionLabel} · specimen ${row.specimen} · day ${row.day}</h3><p>${esc(row.description)}</p><p class="tiny">Stem length is from the soil surface to the stem tip. Leaf spread is the width across both illustrated leaves.</p></div><button type="button" class="primary" data-ps-keep ${s.observations.includes(row.id)?'disabled':''}>${s.observations.includes(row.id)?'This observation is kept':'Keep this observation'}</button><p><button class="secondary" type="button" data-ps-page="compare">Compare what we notice →</button></p>`;
 if(s.page==='compare')return `<h2 id="ps-title" tabindex="-1">I see… I think…</h2><p>Stay with model day ${s.day}, or choose another day. Try saying what the picture shows before explaining it.</p><div class="ps-comparison">${PLANT_CONDITIONS.map(c=>{const a=plantObservation(s.day,c.id,'A'),b=plantObservation(s.day,c.id,'B');return `<p><strong>${c.label}</strong>: A ${a.stemMm} mm, B ${b.stemMm} mm. ${esc(a.leafColour)} leaves; ${esc(a.stemForm)}.</p>`;}).join('')}</div>${plantQuestions(s.day).map(q=>question(q,s)).join('')}<p>Talk together: “I see…” and “I think this might mean…” The game does not judge your explanation.</p><button class="primary" type="button" data-ps-page="plan">Bring an observation to a plan →</button>`;
 return `<h2 id="ps-title" tabindex="-1">Where could our cress shelf go?</h2><p>We’re planning for these cress seedlings, not for every kind of plant. Which place would you try?</p><div class="ps-choices">${[['light','A shelf with adequate light'],['dim','A shelf with too little light'],['unsure','I’m still deciding']].map(([id,label])=>button('location',id,label,s.location===id)).join('')}</div>${s.location?`<p class="ps-feedback" id="ps-location" tabindex="-1" role="status">${s.day===0?'The day-0 groups match. Choose a later model day to compare changes before explaining your shelf choice. Your plan can stay while you look.':s.location==='light'?'Adequate light fits the greener, broader-leaved examples in this model. Other growing conditions matter too.':s.location==='dim'?'Keep your plan if you like, but look again at the paler, thin-stemmed examples. Would adequate light be worth trying for these seedlings?':'Keep looking or talk it through. You can carry an observation while still deciding.'}</p>`:''}<div class="ps-selected"><h3>Selected evidence · day ${row.day}, ${row.conditionLabel}, ${row.specimen}</h3><p>${esc(row.description)}</p>${s.observations.includes(row.id)?'<p>This observation is in your notebook.</p>':'<p>Keep this observation on the Inspect page, or select a kept row below.</p>'}</div><button type="button" class="primary" data-ps-carry ${!s.location||!s.observations.includes(row.id)?'disabled':''}>Carry this observation to my planting corner →</button><details class="ps-water"><summary>Another investigation: what about water?</summary>${question(waterComparisonQuestion,s)}</details>`;
}
function help(s){return `<aside class="ps-help"><div class="ps-support"><button type="button" class="secondary" data-ps-support="help">A looking clue</button><button type="button" class="secondary" data-ps-support="example">A different example</button><button type="button" class="secondary" data-ps-support="together" aria-pressed="${!!s.support.together}">${s.support.together?'Working together is kept':'We’re working together'}</button></div>${s.support.help?'<p>Compare the same day. Find the soil line, follow the stem to its tip, then notice the leaves. A length tells only part of the story.</p>':''}${s.support.example?'<p>Imagine two paper flags: one has a long thin pole and a small flag; the other has a short wide pole and a broad flag. “Longer pole” describes one feature. It does not describe the whole flag.</p>':''}<span data-ps-audio>${hearButton('The storm damaged the growing shelf. Compare the same model day, look at stems and leaves, and keep an observation. These pictures and numbers were invented for comparing.','Hear the invitation')}</span></aside>`;}
export function plantStudyEntry(){return '<aside class="ps-entry"><div><h2>A growing shelf after the storm</h2><p>Inspect seedlings, collect observations and plan a place to grow.</p></div><a class="secondary" href="#living/plants">Investigate the seedlings →</a></aside>';}
export function plantStudyPage(state){const s=plantStudy(state);if(!s)return '<section class="panel"><h1 id="ps-title" tabindex="-1">An earlier plant notebook is kept</h1><p>This format cannot be opened here. Its exact record remains in notes downloads.</p><button type="button" class="secondary" data-ps-recover>Keep the earlier record and start fresh</button></section>';return `<div class="ps-workspace"><header><a class="back" href="#living">← Living Garden</a><h1>Seedlings after the storm</h1></header><nav class="ps-steps" aria-label="Seedling investigation">${steps.map(([id,label],i)=>button('page',id,`${i+1}. ${label}`,s.page===id)).join('')}</nav><div class="ps-layout">${source(s)}<section class="ps-task">${task(s)}</section></div>${keptTable(s)}${help(s)}<p><a href="#living">Take a break in the Living Garden</a> · <a href="#notes">Grown-up notes</a></p></div>`;}
export function plantPlanPanel(state){const s=plantStudy(state),p=s?.plan;if(!p)return '';const r=p.observation;return `<aside class="ps-entry ps-carried"><div><h2>A plan from the growing shelf</h2><p><strong>${locationName(p.location)}</strong> · model day ${esc(r.day)}, ${esc(r.conditionLabel)}, specimen ${esc(r.specimen)}</p><p>${esc(r.description)}</p>${notice()}<p class="tiny">A frozen observation from your notebook. Earlier reading and thinking help travels with it. This plan does not grow or harvest the pretend planting beds.</p></div><a class="secondary" href="#living/plants">Return to my investigation</a></aside>`;}
export function bindPlantStudy(state,ctx){const refresh=(selector='#ps-title')=>{ctx.save();ctx.render();ctx.focus?.(selector);};const act=(fn,selector)=>{if(fn())refresh(selector);};document.querySelectorAll('[data-ps-page]').forEach(b=>b.onclick=()=>act(()=>setPlantPage(state,b.dataset.psPage)));document.querySelectorAll('[data-ps-day]').forEach(b=>b.onclick=()=>act(()=>setPlantDay(state,Number(b.dataset.psDay)),`[data-ps-day="${b.dataset.psDay}"]`));document.querySelectorAll('[data-ps-specimen]').forEach(b=>b.onclick=()=>act(()=>setPlantSpecimen(state,...b.dataset.psSpecimen.split(':')),`[data-ps-specimen="${b.dataset.psSpecimen}"]`));document.querySelectorAll('[data-ps-prediction]').forEach(b=>b.onclick=()=>act(()=>setPlantPrediction(state,b.dataset.psPrediction),'#ps-prediction'));document.querySelector('[data-ps-keep]')?.addEventListener('click',()=>act(()=>recordPlantObservation(state),'#ps-notebook-title'));document.querySelectorAll('[data-ps-row]').forEach(b=>b.onclick=()=>{const r=plantObservationById(b.dataset.psRow);setPlantDay(state,r.day);setPlantSpecimen(state,r.condition,r.specimen);refresh('#ps-title');});document.querySelectorAll('[data-ps-answer]').forEach(b=>b.onclick=()=>{const [id,choice]=b.dataset.psAnswer.split(':');act(()=>answerPlantQuestion(state,id,choice),`#ps-feedback-${id}`);});document.querySelectorAll('[data-ps-location]').forEach(b=>b.onclick=()=>act(()=>choosePlantLocation(state,b.dataset.psLocation),'#ps-location'));document.querySelectorAll('[data-ps-support]').forEach(b=>b.onclick=()=>act(()=>usePlantSupport(state,b.dataset.psSupport),'.ps-help'));document.querySelectorAll('[data-ps-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{usePlantSupport(state,'audio');ctx.save();}));document.querySelector('[data-ps-recover]')?.addEventListener('click',()=>act(()=>recoverPlantStudy(state)));document.querySelector('[data-ps-carry]')?.addEventListener('click',()=>{if(carryPlantPlan(state,currentPlantObservation(state).id)){ctx.save();window.addEventListener('hashchange',()=>ctx.focus?.('.ps-carried'),{once:true});ctx.navigate('#regrow');}});}
export function plantStudyNotes(state){if(!Object.hasOwn(state,'plantStudy'))return '';return `<details class="panel"><summary>Seedling investigation</summary><p>Invented model observations, not real cress measurements. Prediction timing, copying rows, supplied-question practice, help and frozen planning evidence stay separate. These records do not establish independent measurement, experimental-design skill or plant health.</p><pre>${esc(JSON.stringify(state.plantStudy,null,2))}</pre></details>`;}
